def parse_range_string(s):
    # Returns (start, end, is_single?) or raises error string
    # For --range: supports "a:b", "a:", ":b", "a" (single)
    # Errors: "Invalid range format" if more than one colon, "cannot parse integer from empty string" if empty parts where needed, "invalid digit found in string" if non-digit
    if ":" in s:
        parts = s.split(":")
        if len(parts) != 2:
            raise Exception("Invalid range format")
        a, b = parts
        # Both empty -> error cannot parse integer from empty string (as observed for ":" and "")
        # Actually for ":" both empty, error is cannot parse...; for "" (no colon) with empty, also cannot parse...
        # For "a:" with a empty? That's ":b" case, start empty means default, not error. So only error if both empty? Or if single ""?
        # For --range, ":" gave cannot parse..., "" gave cannot parse...
        # For "a:" with a non-empty, b empty means open-ended, no error. Similarly ":b".
        # So logic: if a=="" and b=="" -> error
        # If a=="" and b!="" -> start default, parse b
        # If a!="" and b=="" -> parse a, end default
        # If both non-empty -> parse both
        if a == "" and b == "":
            raise Exception("cannot parse integer from empty string")
        start = None
        end = None
        if a != "":
            # parse a as int
            a_stripped = a
            # check for spaces? " 1:2" gave invalid digit, so spaces are invalid (not stripped). So don't strip.
            if a_stripped == "":
                raise Exception("cannot parse integer from empty string")
            # check digits: must be all digits? For "-1", contains '-', invalid digit (except for scale case where -1 gives range error? But for range, "-1" via = would give invalid digit? We saw highlight '-1' via = gave invalid digit. Good.)
            for ch in a_stripped:
                if ch < '0' or ch > '9':
                    raise Exception("invalid digit found in string")
            try:
                start = int(a_stripped)
            except:
                raise Exception("invalid digit found in string")
        if b != "":
            for ch in b:
                if ch < '0' or ch > '9':
                    raise Exception("invalid digit found in string")
            try:
                end = int(b)
            except:
                raise Exception("invalid digit found in string")
        return (start, end)
    else:
        # single number
        if s == "":
            raise Exception("cannot parse integer from empty string")
        for ch in s:
            if ch < '0' or ch > '9':
                raise Exception("invalid digit found in string")
        try:
            v = int(s)
        except:
            raise Exception("invalid digit found in string")
        return (v, v)

